await p.goto('http://127.0.0.1:54569/pipeline');
await p.waitForTimeout(1000);
const names = () => p.$$eval('#pl .nm', n=>n.map(x=>x.textContent));
async function drag(from, to){
  const hs = await p.$$('#pl li');
  const names0 = await names();
  const hEl = await p.locator('#pl li', {hasText: from}).locator('.h').boundingBox();
  const tEl = await p.locator('#pl li', {hasText: to}).boundingBox();
  await p.mouse.move(hEl.x+hEl.width/2, hEl.y+hEl.height/2);
  await p.mouse.down();
  const ty = tEl.y + 2;  // upper part of target
  await p.mouse.move(hEl.x+hEl.width/2, ty, {steps:15});
  await p.mouse.up();
}
await drag('Picking','Packing');
console.log(await names());
await drag('Quality check','Credit check');
